// The glance feature's graph-platform surface (#4185, epic #3604) — the modules a graph-loaded Glance
// imports but does NOT redraw. Registered HERE, inside the feature, because the shell must not reach a
// feature's internals (#1545). The glance host calls this at module load, before the graph page loads.
// Mirrors the fleet/automations/security/github/skills/mcp graph-platforms.
//
// This is the biggest injected surface of any page, and deliberately so: Glance is a COCKPIT. Its 860-line
// workspace is thin over ~17 hooks and pure derivations (the project graph, the fleet roll-up, stream
// progress, fault health, resume), and every one of them reaches the store, the log tail, or a bsc store.
// "Presentation is data, behavior stays code" puts all of it here — what moves to the graph is the layout.
//
// The last few are not glance's own: Glance composes other features' surfaces (teams, the studio
// sessions, the designs library, the debug pane) and reaches two app-owned console internals. Those
// couplings already exist in the live source — this registers what the page ALREADY imports, and adds no
// new dependency.
//
// THE FLEET PAGE IS GLANCE'S NOW (`repoint-glance-and-github-off-the-deleted-ui`). It lived under
// `features/planner/fleet/` because that is where the fleet is PLANNED, but fleet analytics moved to
// Glance in #2223/#2228 and nothing else has mounted it since — so the code sat in one feature while
// belonging to another. That mattered concretely: the planner-UI deletion would have taken Glance's
// Fleet tab with it, and the directory name gave no hint. Nine records moved to
// `features/glance/fleet/`; the planner keeps the fleet DOMAIN (planFleet, teamFleet, workerScope,
// flowPermissions), which is genuinely its own.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
// — glance's own domain: the hooks + pure derivations the cockpit is thin over —
import * as AgentStall from "@/features/glance/lib/agentStall";
import * as ExpandNode from "@/features/glance/lib/expandNode";
import * as FleetPlanProgress from "@/features/glance/lib/fleetPlanProgress";
import * as GlanceCanvas from "@/features/glance/GlanceCanvas";
import * as GlanceChatDock from "@/features/glance/GlanceChatDock";
import * as GlanceData from "@/features/glance/lib/glanceData";
import * as GlanceFleet from "@/features/glance/lib/glanceFleet";
import * as GlanceGraph from "@/features/glance/lib/glanceGraph";
import * as GlancePush from "@/features/glance/lib/glancePush";
import * as MorphGrid from "@/features/glance/lib/morphGrid";
import * as ResumeProject from "@/features/glance/lib/resumeProject";
import * as StreamProgress from "@/features/glance/lib/streamProgress";
import * as StudioProject from "@/features/glance/lib/studioProject";
import * as UseFleetHeld from "@/features/glance/lib/useFleetHeld";
import * as UseFleetIssueState from "@/features/glance/lib/useFleetIssueState";
import * as UseGlanceFaults from "@/features/glance/lib/useGlanceFaults";
import * as UseGlanceProjects from "@/features/glance/lib/useGlanceProjects";
import * as UseProjectComplete from "@/features/glance/lib/useProjectComplete";
import * as UseProjectFleet from "@/features/glance/lib/useProjectFleet";
import * as UseStreamProgress from "@/features/glance/lib/useStreamProgress";
import * as UsePreviewReview from "@/features/glance/usePreviewReview";
import * as GlanceNodeMotion from "@/features/glance/glanceNodeMotion";
// — the surfaces Glance COMPOSES from elsewhere —
import * as FleetGraphHost from "@/features/glance/fleet/FleetGraphHost";
import * as TeamFleet from "@/features/planner/fleet/teamFleet";
import * as StudioSessions from "@/features/studio-sessions";
import * as Designs from "@/features/designs";
import * as Debug from "@/features/debug";
import * as Teams from "@/features/teams";
import * as PaneIdentity from "@/app/console/lib/paneIdentity";
import * as TerminalSlot from "@/app/console/terminal/TerminalSlot";
import * as GraphPlatform from "@/features/glance/graphPlatform";

/** Register the Glance page's injected graph-platform modules by the specifiers it imports.
 *
 *  Idempotent, and holding NO MODULE STATE on purpose. `registerAppModule` is a Map set, so calling
 *  this twice writes the same entries twice and changes nothing — the `done` flag this used to carry
 *  saved Map writes, it never guarded correctness. It had to go: `bsc graph impl set` refuses a
 *  `provides` from a stateful record onto a REGISTERED specifier, because the record wins over the
 *  registry and would vendor a second copy of that state to every graph consumer.
 */
export function registerGlancePlatform(): void {
  registerAppModule("@/features/glance/lib/agentStall", AgentStall);
  registerAppModule("@/features/glance/lib/fleetPlanProgress", FleetPlanProgress);
  // The expand-click decision (#expanding-a-node-resumes-its-session) — a page record IS the page, so
  // an import it cannot resolve ships a blank screen; `bsc ui set` refuses the write without this.
  registerAppModule("@/features/glance/lib/expandNode", ExpandNode);
  // The two sibling COMPONENTS the page composes. They used to be special-cased in the projection —
  // rewritten to `@/components/<id>`, a form only the graph loader resolves — which is precisely what
  // made `glancepage` un-retirable (`graph-only-record-cannot-back-a-file`). Registered like every other
  // glance module, the page imports them by specifier and the record becomes bundle-resolvable.
  registerAppModule("@/features/glance/GlanceCanvas", GlanceCanvas);
  registerAppModule("@/features/glance/GlanceChatDock", GlanceChatDock);
  registerAppModule("@/features/glance/lib/glanceData", GlanceData);
  registerAppModule("@/features/glance/lib/glanceFleet", GlanceFleet);
  registerAppModule("@/features/glance/lib/glanceGraph", GlanceGraph);
  registerAppModule("@/features/glance/lib/glancePush", GlancePush);
  registerAppModule("@/features/glance/lib/morphGrid", MorphGrid);
  registerAppModule("@/features/glance/lib/resumeProject", ResumeProject);
  registerAppModule("@/features/glance/lib/streamProgress", StreamProgress);
  registerAppModule("@/features/glance/lib/studioProject", StudioProject);
  registerAppModule("@/features/glance/lib/useFleetHeld", UseFleetHeld);
  registerAppModule("@/features/glance/lib/useFleetIssueState", UseFleetIssueState);
  registerAppModule("@/features/glance/lib/useGlanceFaults", UseGlanceFaults);
  registerAppModule("@/features/glance/lib/useGlanceProjects", UseGlanceProjects);
  registerAppModule("@/features/glance/lib/useProjectComplete", UseProjectComplete);
  registerAppModule("@/features/glance/lib/useProjectFleet", UseProjectFleet);
  registerAppModule("@/features/glance/lib/useStreamProgress", UseStreamProgress);
  registerAppModule("@/features/glance/usePreviewReview", UsePreviewReview);
  registerAppModule("@/features/glance/glanceNodeMotion", GlanceNodeMotion);
  registerAppModule("@/features/glance/fleet/FleetGraphHost", FleetGraphHost);
  registerAppModule("@/features/planner/fleet/teamFleet", TeamFleet);
  registerAppModule("@/features/studio-sessions", StudioSessions);
  registerAppModule("@/features/designs", Designs);
  registerAppModule("@/features/debug", Debug);
  registerAppModule("@/features/teams", Teams);
  registerAppModule("@/app/console/lib/paneIdentity", PaneIdentity);
  registerAppModule("@/app/console/terminal/TerminalSlot", TerminalSlot);
  registerAppModule("@/features/glance/graphPlatform", GraphPlatform);
}
